package dev.livingrealms.minecraft.client;import com.mojang.blaze3d.vertex.*;import dev.livingrealms.LivingRealms;import dev.livingrealms.minecraft.entity.LivingRealmsAircraftEntity;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.resources.ResourceLocation;
public final class AircraftModel extends EntityModel<LivingRealmsAircraftEntity>{public static final ModelLayerLocation LAYER=new ModelLayerLocation(ResourceLocation.fromNamespaceAndPath(LivingRealms.MOD_ID,"aircraft"),"main");private final ModelPart fuselage,wings,tail;public AircraftModel(ModelPart r){fuselage=r.getChild("fuselage");wings=r.getChild("wings");tail=r.getChild("tail");}public static LayerDefinition createBodyLayer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();r.addOrReplaceChild("fuselage",CubeListBuilder.create().texOffs(0,0).addBox(-2,-2,-10,4,4,20),PartPose.offset(0,16,0));r.addOrReplaceChild("wings",CubeListBuilder.create().texOffs(0,24).addBox(-14,-1,-3,28,2,7),PartPose.offset(0,16,0));r.addOrReplaceChild("tail",CubeListBuilder.create().texOffs(0,34).addBox(-6,-1,0,12,2,5).texOffs(36,34).addBox(-1,-7,2,2,7,4),PartPose.offset(0,15,8));return LayerDefinition.create(m,64,64);}public void setupAnim(LivingRealmsAircraftEntity e,float s,float a,float age,float yaw,float pitch){}public void renderToBuffer(PoseStack p,VertexConsumer b,int l,int o,int c){fuselage.render(p,b,l,o,c);wings.render(p,b,l,o,c);tail.render(p,b,l,o,c);}}
